/*
    Dashboard Tổng hợp — DASH_MainSummary_GetData
    Gom KPI từ các module: Tổng quan, Sĩ số lớp, Tốt nghiệp, Công nợ,
    Rèn luyện, Kỷ luật, Khen thưởng, Giảng dạy & Thư viện.

    @YearID, @Semester — tuỳ chọn (bắt buộc cho rèn luyện / kỷ luật / khen thưởng / tốt nghiệp chi tiết)
    @ScienceID, @CourseID — tuỳ chọn
    @ResultSet: 1 = danh sách KPI phẳng; 2 = cảnh báo; NULL = cả hai
*/

IF OBJECT_ID(N'dbo.DASH_MainSummary_GetData', N'P') IS NOT NULL
    DROP PROCEDURE dbo.DASH_MainSummary_GetData;
GO

CREATE PROCEDURE dbo.DASH_MainSummary_GetData
(
    @YearID int = NULL,
    @Semester tinyint = NULL,
    @ScienceID nvarchar(50) = NULL,
    @CourseID nvarchar(50) = NULL,
    @ResultSet tinyint = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    Declare @CalendarYear int;
    Set @CalendarYear = Year(GetDate());

    Create Table #tblMetrics
    (
        SectionGroup nvarchar(50),
        SectionTitle nvarchar(200),
        MetricKey nvarchar(80),
        MetricLabel nvarchar(200),
        MetricValue nvarchar(100),
        MetricNote nvarchar(500),
        ColorClass nvarchar(30),
        SortOrder int
    );

    Select
        SIM_Class.ClassID,
        SIM_Class.ClassName,
        SIM_Class.ScienceID,
        SIM_Science.ScienceName,
        SIM_Class.CourseID,
        SIM_Course.CourseName,
        ISNULL(tblStudent.TotalStudent, 0) as NowStudentCount,
        ISNULL(tblStudent.StudyQuantity, 0) as StudyQuantity,
        ISNULL(tblStudent.GraduationQuantity, 0) as GraduationQuantity,
        ISNULL(tblStudent.WarningQuantity, 0) as WarningQuantity,
        ISNULL(tblStudent.MaleQuantity, 0) as MaleQuantity,
        ISNULL(tblStudent.FemaleQuantity, 0) as FemaleQuantity,
        ISNULL(tblStudent.DebtStudentCount, 0) as DebtStudentCount,
        ISNULL(tblStudent.TotalDebtMoney, 0) as TotalDebtMoney
    Into #tblClassData
    From SIM_Class
        Inner Join SIM_Course On SIM_Course.CourseID = SIM_Class.CourseID
        Inner Join SIM_Science On SIM_Science.ScienceID = SIM_Class.ScienceID
        Left Join
        (
            Select
                SIM_Student.ClassID,
                Count(*) as TotalStudent,
                Sum(Case when SIM_Student.Status = 1 then 1 else 0 end) as StudyQuantity,
                Sum(Case when SIM_Student.Status = 2 then 1 else 0 end) as GraduationQuantity,
                Sum(Case when SIM_Student.Status not in (1, 2) then 1 else 0 end) as WarningQuantity,
                Sum(Case when SIM_Student.Gender = 1 And SIM_Student.Status in (1, 2) then 1 else 0 end) as MaleQuantity,
                Sum(Case when SIM_Student.Gender = 0 And SIM_Student.Status in (1, 2) then 1 else 0 end) as FemaleQuantity,
                Sum(Case when SIM_Student.Status = 1 And ISNULL(SIM_Student.DebtMoney, 0) > 0 then 1 else 0 end) as DebtStudentCount,
                Sum(Case when SIM_Student.Status = 1 then ISNULL(SIM_Student.DebtMoney, 0) else 0 end) as TotalDebtMoney
            From SIM_Student
            Where SIM_Student.IsDeleted = 0
            Group by SIM_Student.ClassID
        ) tblStudent on tblStudent.ClassID = SIM_Class.ClassID
    Where SIM_Class.IsActived = 1
        And SIM_Class.ClassType = 0
        And (@ScienceID is null or @ScienceID = N'' or SIM_Class.ScienceID = @ScienceID)
        And (@CourseID is null or @CourseID = N'' or SIM_Class.CourseID = @CourseID);

    /* --- KPI Tổng quan --- */
    Declare @TotalStudent int;
    Declare @StudyingStudent int;
    Declare @GraduatedStudent int;
    Declare @WarningStudent int;
    Declare @TotalClass int;
    Declare @TotalTeacher int;
    Declare @TotalScience int;
    Declare @TotalCourse int;
    Declare @TotalDebtMoney decimal(18, 0);
    Declare @DebtStudentCount int;
    Declare @FeeRate decimal(18, 1);
    Declare @GraduationRate decimal(18, 1);
    Declare @TotalBooks int;
    Declare @MaleStudent int;
    Declare @FemaleStudent int;
    Declare @RegisterYear int;
    Declare @EnrollYear int;
    Declare @TeachingUnit decimal(18, 0);

    Select
        @TotalClass = COUNT(*),
        @TotalStudent = ISNULL(SUM(NowStudentCount), 0),
        @StudyingStudent = ISNULL(SUM(StudyQuantity), 0),
        @GraduatedStudent = ISNULL(SUM(GraduationQuantity), 0),
        @WarningStudent = ISNULL(SUM(WarningQuantity), 0),
        @MaleStudent = ISNULL(SUM(MaleQuantity), 0),
        @FemaleStudent = ISNULL(SUM(FemaleQuantity), 0),
        @DebtStudentCount = ISNULL(SUM(DebtStudentCount), 0),
        @TotalDebtMoney = ISNULL(SUM(TotalDebtMoney), 0)
    From #tblClassData;

    Select @TotalTeacher = COUNT(*)
    From SIM_Teacher
    Where ISNULL(SIM_Teacher.IsDeleted, 0) = 0;

    Select @TotalScience = COUNT(Distinct ScienceID) From #tblClassData;
    Select @TotalCourse = COUNT(Distinct CourseID) From #tblClassData;

    If @StudyingStudent > 0
        Set @FeeRate = Round(((@StudyingStudent - @DebtStudentCount) * 100.0) / @StudyingStudent, 1);
    Else
        Set @FeeRate = 0;

    If (@StudyingStudent + @GraduatedStudent) > 0
        Set @GraduationRate = Round((@GraduatedStudent * 100.0) / (@StudyingStudent + @GraduatedStudent), 1);
    Else
        Set @GraduationRate = 0;

    Set @TotalBooks = 0;
    If OBJECT_ID(N'dbo.LIB_Book', N'U') IS NOT NULL
    Begin
        Select @TotalBooks = COUNT(*)
        From LIB_Book
        Where ISNULL(LIB_Book.IsDeleted, 0) = 0;
    End

    Select @RegisterYear = COUNT(*)
    From SIM_Student
        Inner Join #tblClassData On #tblClassData.ClassID = SIM_Student.ClassID
    Where SIM_Student.IsDeleted = 0
        And SIM_Student.CreatedDate is not null
        And Year(SIM_Student.CreatedDate) = @CalendarYear;

    Select @EnrollYear = COUNT(*)
    From SIM_Student
        Inner Join #tblClassData On #tblClassData.ClassID = SIM_Student.ClassID
    Where SIM_Student.IsDeleted = 0
        And SIM_Student.Status in (1, 2)
        And ISNULL(SIM_Student.RealLearningDate, SIM_Student.ReceivedDate) is not null
        And Year(ISNULL(SIM_Student.RealLearningDate, SIM_Student.ReceivedDate)) = @CalendarYear;

    Set @TeachingUnit = 0;
    If OBJECT_ID(N'dbo.SIM_Class_Subject', N'U') IS NOT NULL
    Begin
        Select @TeachingUnit = ISNULL(Sum(ISNULL(SIM_Class_Subject.UnitText, 0)), 0)
        From SIM_Class_Subject
            Inner Join #tblClassData On #tblClassData.ClassID = SIM_Class_Subject.ClassID;
    End

    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'overview', N'Tổng quan hệ thống', N'totalStudent', N'Tổng sinh viên', Cast(@TotalStudent as nvarchar(20)), N'trong phạm vi lọc', N'blue', 101),
        (N'overview', N'Tổng quan hệ thống', N'studyingStudent', N'SV đang học', Cast(@StudyingStudent as nvarchar(20)), N'đang theo học', N'teal', 102),
        (N'overview', N'Tổng quan hệ thống', N'graduatedStudent', N'SV đã tốt nghiệp', Cast(@GraduatedStudent as nvarchar(20)), N'hoàn thành chương trình', N'green', 103),
        (N'overview', N'Tổng quan hệ thống', N'totalTeacher', N'Tổng giáo viên', Cast(@TotalTeacher as nvarchar(20)), N'đang hoạt động', N'purple', 104),
        (N'overview', N'Tổng quan hệ thống', N'totalClass', N'Tổng lớp học', Cast(@TotalClass as nvarchar(20)), N'lớp đang mở', N'teal', 105),
        (N'overview', N'Tổng quan hệ thống', N'totalScience', N'Số khoa / ngành', Cast(@TotalScience as nvarchar(20)), N'đang có lớp', N'blue', 106),
        (N'overview', N'Tổng quan hệ thống', N'totalCourse', N'Số khóa học', Cast(@TotalCourse as nvarchar(20)), N'đang có lớp', N'blue', 107),
        (N'overview', N'Tổng quan hệ thống', N'graduationRate', N'Tỷ lệ tốt nghiệp', Cast(@GraduationRate as nvarchar(20)) + N'%', N'trên SV đang học + TN', N'green', 108),
        (N'overview', N'Tổng quan hệ thống', N'warningStudent', N'SV cảnh báo / nghỉ', Cast(@WarningStudent as nvarchar(20)), N'ngoài đang học & TN', N'yellow', 109);

    /* --- KPI Sĩ số lớp --- */
    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'classSize', N'Sĩ số lớp', N'totalClass', N'Tổng số lớp', Cast(@TotalClass as nvarchar(20)), N'lớp trong phạm vi lọc', N'teal', 201),
        (N'classSize', N'Sĩ số lớp', N'totalStudent', N'Tổng sinh viên', Cast(@TotalStudent as nvarchar(20)), N'tất cả trạng thái', N'blue', 202),
        (N'classSize', N'Sĩ số lớp', N'studyingStudent', N'SV đang học', Cast(@StudyingStudent as nvarchar(20)), N'status đang học', N'orange', 203),
        (N'classSize', N'Sĩ số lớp', N'maleStudent', N'Sinh viên nam', Cast(@MaleStudent as nvarchar(20)), N'đang học + TN', N'blue', 204),
        (N'classSize', N'Sĩ số lớp', N'femaleStudent', N'Sinh viên nữ', Cast(@FemaleStudent as nvarchar(20)), N'đang học + TN', N'purple', 205),
        (N'classSize', N'Sĩ số lớp', N'warningStudent', N'SV nghỉ / cảnh báo', Cast(@WarningStudent as nvarchar(20)), N'cần theo dõi sĩ số', N'yellow', 206),
        (N'classSize', N'Sĩ số lớp', N'graduatedStudent', N'SV đã tốt nghiệp', Cast(@GraduatedStudent as nvarchar(20)), N'trong phạm vi lọc', N'green', 207);

    /* --- KPI Tốt nghiệp --- */
    Declare @GradReview int;
    Declare @GradEligible int;
    Declare @GradNotEligible int;
    Declare @GradEligibleRate decimal(18, 1);

    Set @GradReview = @StudyingStudent + @GraduatedStudent;
    Set @GradEligible = 0;
    Set @GradNotEligible = 0;
    Set @GradEligibleRate = 0;

    If @YearID IS NOT NULL And @Semester IS NOT NULL
    Begin
        Select @GradEligible = COUNT(Distinct SIM_GraduationResult.StudentID)
        From SIM_GraduationResult
            Inner Join SIM_Student On SIM_Student.StudentID = SIM_GraduationResult.StudentID
            Inner Join #tblClassData On #tblClassData.ClassID = SIM_Student.ClassID
        Where SIM_GraduationResult.ResultReview = 1
            And SIM_GraduationResult.YearID = @YearID
            And SIM_Student.IsDeleted = 0
            And
            (
                ISNULL(SIM_GraduationResult.CerIssued, 0) = 1
                Or ISNULL(SIM_GraduationResult.GraduationLevel, N'') <> N''
                Or ISNULL(SIM_GraduationResult.DecisionNo, N'') <> N''
            );

        Set @GradNotEligible = Case when @GradReview - @GradEligible < 0 then 0 else @GradReview - @GradEligible end;
        If @GradReview > 0
            Set @GradEligibleRate = Round((@GradEligible * 100.0) / @GradReview, 1);
    End

    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'graduation', N'Tốt nghiệp', N'totalReviewStudent', N'SV xét tốt nghiệp', Cast(@GradReview as nvarchar(20)), N'đang học + đã TN', N'blue', 301),
        (N'graduation', N'Tốt nghiệp', N'eligibleStudent', N'Đủ điều kiện TN', Cast(@GradEligible as nvarchar(20)), Case when @YearID IS NULL then N'chọn năm học / HK để xem chi tiết' else N'theo kết quả xét TN' end, N'green', 302),
        (N'graduation', N'Tốt nghiệp', N'notEligibleStudent', N'Chưa đủ điều kiện', Cast(@GradNotEligible as nvarchar(20)), N'cần bổ sung hồ sơ / điểm', N'yellow', 303),
        (N'graduation', N'Tốt nghiệp', N'eligibleRate', N'Tỷ lệ đủ điều kiện', Cast(@GradEligibleRate as nvarchar(20)) + N'%', N'trên SV xét TN', N'green', 304),
        (N'graduation', N'Tốt nghiệp', N'graduatedStudent', N'SV đã tốt nghiệp', Cast(@GraduatedStudent as nvarchar(20)), N'trong hệ thống', N'teal', 305),
        (N'graduation', N'Tốt nghiệp', N'graduationRate', N'Tỷ lệ tốt nghiệp', Cast(@GraduationRate as nvarchar(20)) + N'%', N'tổng quan toàn trường', N'purple', 306);

    /* --- KPI Công nợ & học phí --- */
    Declare @PlanMoney decimal(18, 0);
    Declare @ReceiptMoney decimal(18, 0);
    Declare @RemainMoney decimal(18, 0);
    Declare @CollectedRate decimal(18, 1);
    Declare @ClassWithDebt int;

    Set @PlanMoney = 0;
    Set @ReceiptMoney = 0;
    Set @RemainMoney = 0;
    Set @CollectedRate = 0;
    Set @ClassWithDebt = 0;

    If OBJECT_ID(N'dbo.ACC_CongNoHocSinh_Dashboard_Web', N'P') IS NOT NULL
    Begin
        Create Table #kpiDebt
        (
            ClassWithDebtCount int,
            TotalClassCount int,
            TotalPlanMoney decimal(18, 0),
            TotalReceiptMoney decimal(18, 0),
            TotalRemainMoney decimal(18, 0),
            CollectedRate decimal(18, 2),
            RemainRate decimal(18, 2)
        );

        Insert Into #kpiDebt
        Exec dbo.ACC_CongNoHocSinh_Dashboard_Web
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ClassID = NULL,
            @YearID = @YearID,
            @Semester = @Semester,
            @ResultSet = 1;

        Select
            @ClassWithDebt = ClassWithDebtCount,
            @PlanMoney = TotalPlanMoney,
            @ReceiptMoney = TotalReceiptMoney,
            @RemainMoney = TotalRemainMoney,
            @CollectedRate = CollectedRate
        From #kpiDebt;

        Drop Table #kpiDebt;
    End

    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'finance', N'Công nợ & học phí', N'totalPlanMoney', N'Tổng phải thu', Cast(@PlanMoney as nvarchar(30)), N'kế hoạch thu theo lớp', N'blue', 401),
        (N'finance', N'Công nợ & học phí', N'totalReceiptMoney', N'Đã thu', Cast(@ReceiptMoney as nvarchar(30)), N'thực thu học phí', N'green', 402),
        (N'finance', N'Công nợ & học phí', N'totalRemainMoney', N'Còn nợ', Cast(@RemainMoney as nvarchar(30)), N'chưa thu đủ', N'red', 403),
        (N'finance', N'Công nợ & học phí', N'collectedRate', N'Tỷ lệ đã thu', Cast(@CollectedRate as nvarchar(20)) + N'%', N'trên tổng phải thu', N'green', 404),
        (N'finance', N'Công nợ & học phí', N'debtStudentCount', N'SV còn nợ HP', Cast(@DebtStudentCount as nvarchar(20)), N'đang học còn công nợ', N'yellow', 405),
        (N'finance', N'Công nợ & học phí', N'totalDebtMoney', N'Tổng nợ học phí', Cast(@TotalDebtMoney as nvarchar(30)), N'trên hồ sơ SV', N'red', 406),
        (N'finance', N'Công nợ & học phí', N'feeRate', N'Tỷ lệ thu HP', Cast(@FeeRate as nvarchar(20)) + N'%', N'SV đang học không nợ', N'teal', 407),
        (N'finance', N'Công nợ & học phí', N'classWithDebt', N'Lớp còn công nợ', Cast(@ClassWithDebt as nvarchar(20)), N'có số dư chưa thu', N'orange', 408);

    /* --- KPI Rèn luyện --- */
    If @YearID IS NOT NULL And @Semester IS NOT NULL
        And OBJECT_ID(N'dbo.DASH_StudentEthic_GetData', N'P') IS NOT NULL
    Begin
        Create Table #kpiEthic
        (
            TotalStudent int,
            EvaluatedStudent int,
            NotEvaluatedStudent int,
            AvgEthicMark decimal(10, 1),
            GoodExcellentRate decimal(10, 1),
            WeakStudentCount int
        );

        Insert Into #kpiEthic
        Exec dbo.DASH_StudentEthic_GetData
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ClassID = NULL,
            @YearID = @YearID,
            @Semester = @Semester,
            @ResultSet = 1;

        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Select
            N'ethic',
            N'Rèn luyện',
            N'totalStudent',
            N'SV trong phạm vi',
            Cast(TotalStudent as nvarchar(20)),
            N'đang học / xét rèn luyện',
            N'blue',
            501
        From #kpiEthic
        Union All
        Select N'ethic', N'Rèn luyện', N'evaluatedStudent', N'Đã chấm điểm', Cast(EvaluatedStudent as nvarchar(20)), N'có điểm rèn luyện', N'green', 502 From #kpiEthic
        Union All
        Select N'ethic', N'Rèn luyện', N'notEvaluatedStudent', N'Chưa chấm', Cast(NotEvaluatedStudent as nvarchar(20)), N'chưa có điểm HK', N'yellow', 503 From #kpiEthic
        Union All
        Select N'ethic', N'Rèn luyện', N'avgEthicMark', N'Điểm TB rèn luyện', Cast(AvgEthicMark as nvarchar(20)), N'trung bình đã chấm', N'teal', 504 From #kpiEthic
        Union All
        Select N'ethic', N'Rèn luyện', N'goodExcellentRate', N'Tỷ lệ Tốt / XS', Cast(GoodExcellentRate as nvarchar(20)) + N'%', N'trên tổng SV', N'green', 505 From #kpiEthic
        Union All
        Select N'ethic', N'Rèn luyện', N'weakStudentCount', N'SV yếu / kém RL', Cast(WeakStudentCount as nvarchar(20)), N'cần theo dõi', N'red', 506 From #kpiEthic;

        Drop Table #kpiEthic;
    End
    Else
    Begin
        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Values (N'ethic', N'Rèn luyện', N'notAvailable', N'Chưa có dữ liệu', N'—', N'vui lòng chọn Năm học và Học kỳ', N'yellow', 501);
    End

    /* --- KPI Kỷ luật --- */
    If @YearID IS NOT NULL And @Semester IS NOT NULL
        And OBJECT_ID(N'dbo.DASH_StudentSanction_GetData', N'P') IS NOT NULL
    Begin
        Create Table #kpiSanction
        (
            TotalSanction int,
            DistinctStudent int,
            ActiveSanction int,
            SuspendedCount int
        );

        Insert Into #kpiSanction
        Exec dbo.DASH_StudentSanction_GetData
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ClassID = NULL,
            @YearID = @YearID,
            @Semester = @Semester,
            @ResultSet = 1;

        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Select N'discipline', N'Kỷ luật', N'totalSanction', N'Tổng quyết định KL', Cast(TotalSanction as nvarchar(20)), N'trong năm học / HK', N'red', 601 From #kpiSanction
        Union All
        Select N'discipline', N'Kỷ luật', N'distinctStudent', N'SV bị kỷ luật', Cast(DistinctStudent as nvarchar(20)), N'không trùng lặp', N'orange', 602 From #kpiSanction
        Union All
        Select N'discipline', N'Kỷ luật', N'activeSanction', N'QĐ còn hiệu lực', Cast(ActiveSanction as nvarchar(20)), N'đang áp dụng', N'yellow', 603 From #kpiSanction
        Union All
        Select N'discipline', N'Kỷ luật', N'suspendedCount', N'SV bị đình chỉ', Cast(SuspendedCount as nvarchar(20)), N'theo quyết định KL', N'red', 604 From #kpiSanction;

        Drop Table #kpiSanction;
    End
    Else
    Begin
        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Values (N'discipline', N'Kỷ luật', N'notAvailable', N'Chưa có dữ liệu', N'—', N'vui lòng chọn Năm học và Học kỳ', N'yellow', 601);
    End

    /* --- KPI Khen thưởng --- */
    If @YearID IS NOT NULL And @Semester IS NOT NULL
        And OBJECT_ID(N'dbo.DASH_StudentReward_GetData', N'P') IS NOT NULL
    Begin
        Create Table #kpiReward
        (
            TotalSanction int,
            DistinctStudent int,
            ActiveSanction int,
            SuspendedCount int
        );

        Insert Into #kpiReward
        Exec dbo.DASH_StudentReward_GetData
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ClassID = NULL,
            @YearID = @YearID,
            @Semester = @Semester,
            @ResultSet = 1;

        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Select N'reward', N'Khen thưởng', N'totalReward', N'Tổng quyết định KT', Cast(TotalSanction as nvarchar(20)), N'trong năm học / HK', N'green', 701 From #kpiReward
        Union All
        Select N'reward', N'Khen thưởng', N'distinctStudent', N'SV được khen thưởng', Cast(DistinctStudent as nvarchar(20)), N'không trùng lặp', N'teal', 702 From #kpiReward
        Union All
        Select N'reward', N'Khen thưởng', N'rewardFormCount', N'Hình thức KT', Cast(ActiveSanction as nvarchar(20)), N'loại khen thưởng', N'blue', 703 From #kpiReward
        Union All
        Select N'reward', N'Khen thưởng', N'multiRewardStudent', N'SV được KT >= 2 lần', Cast(SuspendedCount as nvarchar(20)), N'khen thưởng nhiều lần', N'purple', 704 From #kpiReward;

        Drop Table #kpiReward;
    End
    Else
    Begin
        Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
        Values (N'reward', N'Khen thưởng', N'notAvailable', N'Chưa có dữ liệu', N'—', N'vui lòng chọn Năm học và Học kỳ', N'yellow', 701);
    End

    /* --- KPI Giảng dạy & Thư viện --- */
    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'teaching', N'Giảng dạy & thư viện', N'teachingUnit', N'Tổng ĐVHT giảng dạy', Cast(@TeachingUnit as nvarchar(20)), N'theo lớp mở', N'blue', 801),
        (N'teaching', N'Giảng dạy & thư viện', N'registerYear', N'Hồ sơ đăng ký (năm)', Cast(@RegisterYear as nvarchar(20)), Cast(@CalendarYear as nvarchar(10)), N'teal', 802),
        (N'teaching', N'Giảng dạy & thư viện', N'enrollYear', N'Hồ sơ nhập học (năm)', Cast(@EnrollYear as nvarchar(20)), Cast(@CalendarYear as nvarchar(10)), N'green', 803),
        (N'teaching', N'Giảng dạy & thư viện', N'totalBooks', N'Đầu sách thư viện', Cast(@TotalBooks as nvarchar(20)), N'trong kho sách', N'purple', 804),
