        sections = sections || [];
        for (i = 0; i < sections.length; i++) {
            html += buildSection(sections[i]);
        }
        root.innerHTML = html;
    }

    function getAlertIcon(code, type) {
        if (code === "warning-debt") {
            return "bi-cash-coin";
        }
        if (code === "warning-failed") {
            return "bi-journal-x";
        }
        if (type === "danger") {
            return "bi-exclamation-octagon-fill";
        }
        return "bi-exclamation-triangle-fill";
    }

    function renderAlerts(rows) {
        var wrap = getEl("schDashAlertsWrap");
        var container = getEl("schDashAlertsList");
        var i;
        var html = "";
        rows = rows || [];
        if (!container) {
            return;
        }
        if (!rows.length) {
            if (wrap) {
                wrap.className = "row sch-dash-row d-none";
            }
            return;
        }
        if (wrap) {
            wrap.className = "row sch-dash-row";
        }
        for (i = 0; i < rows.length; i++) {
            var row = rows[i];
            var type = row.AlertType || "warning";
            var icon = getAlertIcon(row.AlertCode, type);
            html += "<div class=\"sch-dash-alert-item " + type + "\">" +
                "<div class=\"sch-dash-alert-icon\"><i class=\"bi " + icon + "\"></i></div>" +
                "<div><div class=\"sch-dash-alert-text\">" + (row.AlertText || "") + "</div>" +
                "<div class=\"sch-dash-alert-meta\">" + (row.AlertMeta || "") + "</div></div></div>";
        }
        container.innerHTML = html;
    }

    function updateTimestamp(text) {
        var el = getEl("schDashUpdateTime");
        if (!el) {
            return;
        }
        if (text) {
            el.textContent = text;
            return;
        }
        var now = new Date();
        var day = ("0" + now.getDate()).slice(-2);
        var month = ("0" + (now.getMonth() + 1)).slice(-2);
        var year = now.getFullYear();
        var hours = ("0" + now.getHours()).slice(-2);
        var minutes = ("0" + now.getMinutes()).slice(-2);
        el.textContent = day + "/" + month + "/" + year + " " + hours + ":" + minutes;
    }

    function applyPayload(data) {
        data = data || {};
        renderSections(data.sections);
        renderAlerts(data.alerts);
        updateTimestamp(data.updatedAt);
    }

    function loadDashboardData() {
        var filters = readFilters();
        showState("loading");
        postJson({
            action: "data",
            yearId: filters.yearId,
            semester: filters.semester,
            scienceId: filters.scienceId,
            courseId: filters.courseId
        }, function (ok, msg, data) {
            if (!ok) {
                showState("error");
                setErrorMessage(msg);
                return;
            }
            showState("ready");
            applyPayload(data);
        });
    }

    function loadDashboard() {
        if (!filtersLoaded) {
            loadAllFilters(function (ok, msg) {
                filtersLoaded = true;
                if (!ok) {
                    showState("error");
                    setErrorMessage(msg);
                    return;
                }
                applyDefaultFilters();
                loadDashboardData();
            });
            return;
        }
        loadDashboardData();
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var refreshBtn = getEl("schDashBtnRefresh");
        var facultyEl = getEl("schDashFilterFaculty");
        var filters = document.querySelectorAll(".sch-dash-main-summary .sch-dash-filter-select");

        if (refreshBtn) {
            refreshBtn.addEventListener("click", function () {
                refreshBtn.classList.add("is-loading");
                loadDashboardData();
                setTimeout(function () {
                    refreshBtn.classList.remove("is-loading");
                }, 600);
            });
        }

        if (facultyEl) {
            facultyEl.addEventListener("change", function () {
                loadCourses(facultyEl.value, function () {
                    loadDashboardData();
                });
            });
        }

        var i;
        for (i = 0; i < filters.length; i++) {
            if (filters[i].id === "schDashFilterFaculty") {
                continue;
            }
            filters[i].addEventListener("change", function () {
                loadDashboardData();
            });
        }
    }

    function initSchoolDashboard() {
        if (!getEl("schDashBtnRefresh")) {
            return;
        }
        bindEvents();
        loadDashboard();
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initSchoolDashboard);
    } else {
        initSchoolDashboard();
    }
})();

